 * options.header does not affect this streaming API: it always yields arrays.
 * @param {{ delimiter?: string, header?: boolean }} [options]
 * @returns {{ push(chunk: string): string[][], end(): string[][] }}
 */
function createParser(options = {}) {
  const delimiter = options.delimiter === undefined ? ',' : options.delimiter;
  if (typeof delimiter !== 'string' || delimiter.length !== 1 ||
      delimiter === '"' || delimiter === '\r' || delimiter === '\n') {
    throw new RangeError('delimiter must be one character other than a quote, CR, or LF');
  }

  let state = FIELD_START;
  let row = [];
  let field = '';
  let rowStarted = false; // any character of the current record was seen
  let skipLF = false;     // previous character was a record-ending CR
  let prevCR = false;     // previous character was CR (CRLF counts as one line)
  let line = 1;
  let started = false;    // any non-empty input seen (BOM handling)
  let ended = false;

  function syntaxError(message) {
    return new SyntaxError(`${message} at line ${line}`);
